			continue
		}
		switch f.Class {
		case scan.ClassOSPackages:
			s.BaseImage++
		case scan.ClassLangPackages:
			s.Dependencies++
		default:
			s.Unclassified++
		}
	}
	return s
}

// Fix is one package that has to move, with every CVE moving it clears.
type Fix struct {
	Class     string
	Ecosystem string
	Package   string
	Installed string
	// Target is the version to move to: the highest of what each CVE needs, so
	// one bump clears them all. Empty when the versions could not be ordered;
	// Options then lists them and none is preferred.
	Target  string
	Options []string
	// Command is the command that performs the move, empty when none is known
	// for the ecosystem or when Target is empty.
	Command  string
	CVEs     []string
	Severity scan.SeverityLevel
}

type fixKey struct{ ecosystem, pkg, installed string }

// Group collects the fixable vulnerabilities into one Fix per (ecosystem,
// package, installed version), worst severity first. A package installed in
// two versions is two fixes: each has its own target.
func Group(findings []scan.Finding) []Fix {
	byKey := map[fixKey]*Fix{}
	var order []fixKey

	for _, f := range findings {
		if scan.Categorize(f) != scan.CategoryVulnerability || f.FixedIn == "" || f.PkgName == "" {
			continue
		}
		key := fixKey{f.Ecosystem, f.PkgName, f.Version}
		fix, seen := byKey[key]
		if !seen {
			fix = &Fix{Class: f.Class, Ecosystem: f.Ecosystem, Package: f.PkgName, Installed: f.Version, Severity: f.Severity}
			byKey[key] = fix
			order = append(order, key)
		}
		fix.CVEs = append(fix.CVEs, f.ID)
		if severityRank(f.Severity) > severityRank(fix.Severity) {
			fix.Severity = f.Severity
		}
		fix.Options = addOption(fix.Options, scan.PickFixed(f.Version, f.FixedIn), f.FixedIn)
	}

	fixes := make([]Fix, 0, len(order))
	for _, key := range order {
		fix := byKey[key]
		resolveTarget(fix)
		fixes = append(fixes, *fix)
	}
	sort.SliceStable(fixes, func(i, j int) bool {
		return severityRank(fixes[i].Severity) > severityRank(fixes[j].Severity)
	})
	return fixes
}

// addOption records the version one CVE needs, once. When PickFixed could not
// choose among several, the raw FixedVersion is kept so the choice stays
// visible to the reader.
func addOption(options []string, picked, raw string) []string {
	v := picked
	if v == "" {
		v = raw
	}
	for _, o := range options {
		if o == v {
			return options
		}
	}
	return append(options, v)
}

// resolveTarget sets Target and Command from the options: the highest one when
// they can all be ordered, nothing otherwise.
func resolveTarget(fix *Fix) {
	if len(fix.Options) == 1 && scan.PickFixed(fix.Installed, fix.Options[0]) != "" {
		fix.Target = fix.Options[0]
	} else if len(fix.Options) > 1 {
		fix.Target = highest(fix.Options)
	}
	if fix.Target != "" {
		fix.Command, _ = scan.FixCommand(fix.Ecosystem, fix.Package, fix.Target)
	}
	sort.Strings(fix.Options)
}

// highest returns the greatest of versions, or "" if any pair cannot be ordered.
func highest(versions []string) string {
	best := versions[0]
	for _, v := range versions[1:] {
		c, ok := scan.CompareVersions(v, best)
		if !ok {
			return ""
		}
		if c > 0 {
			best = v
		}
	}
	if scan.PickFixed("", best) == "" {
		return ""
	}
	return best
}

func severityRank(s scan.SeverityLevel) int {
	switch s {
	case scan.SeverityCritical:
		return 4
	case scan.SeverityHigh:
		return 3
	case scan.SeverityMedium:
		return 2
	case scan.SeverityLow:
		return 1
	}
	return 0
}
